  5	newtype Odd = n : int | IsOdd(n) witness 3
  6	
  7	trait OddListSpec
  8	{
  9	    var s: seq<Odd>
 10	    var capacity: nat
 11	
 12	    predicate Valid()
 13	        reads this
 14	    {
 15	        0 <= |s| <= this.capacity &&
 16	        forall i :: 0 <= i < |s| ==> IsOdd(s[i] as int)
 17	    }
 18	
 19	    method insert(index: nat, element: Odd)
 20	        modifies this
 21	        requires 0 <= index <= |s|
 22	        requires |s| + 1 <= this.capacity
 23	        ensures |s| == |old(s)| + 1
 24	        ensures s[index] == element
 25	        ensures old(capacity) == capacity
 26	        ensures Valid()
 27	
 28	    method pushFront(element: Odd)
 29	        modifies this
 30	        requires |s| + 1 <= this.capacity
 31	        ensures |s| == |old(s)| + 1
 32	        ensures s[0] == element
 33	        ensures old(capacity) == capacity
 34	        ensures Valid()
 35	
 36	    method pushBack(element: Odd)
 37	        modifies this
 38	        requires |s| + 1 <= this.capacity
 39	        ensures |s| == |old(s)| + 1
 40	        ensures s[|s| - 1] == element
 41	        ensures old(capacity) == capacity
 42	        ensures Valid()
 43	
 44	    method remove(element: Odd)
 45	        modifies this
 46	        requires Valid()
 47	        requires |s| > 0
 48	        requires element in s
 49	        ensures |s| == |old(s)| - 1
 50	        ensures old(capacity) == capacity
 51	        ensures Valid()
 52	
 53	    method removeAtIndex(index: nat)
 54	        modifies this
 55	        requires Valid()
 56	        requires |s| > 0
 57	        requires 0 <= index < |s|
 58	        ensures |s| == |old(s)| - 1
 59	        ensures old(capacity) == capacity
 60	        ensures Valid()
 61	
 62	    method popFront() returns (x: Odd)
 63	        modifies this
 64	        requires Valid()
 65	        requires |s| > 0
 66	        ensures old(s)[0] == x
 67	        ensures |s| == |old(s)| - 1
 68	        ensures old(capacity) == capacity
 69	        ensures Valid()
 70	
 71	    method popBack() returns (x: Odd)
 72	        modifies this
 73	        requires Valid()
 74	        requires |s| > 0
 75	        ensures old(s)[|old(s)| - 1] == x
 76	        ensures |s| == |old(s)| - 1
 77	        ensures old(capacity) == capacity
 78	        ensures Valid()
