 92	        requires Valid()
 93	        requires l2.Valid()
 94	        requires this.capacity >= 0 
 95	        requires l2.capacity >= 0 
 96	        requires forall i, j :: 0 <= i < j < |s| ==> s[i] <= s[j]
 97	        requires forall i, j :: 0 <= i < j < |l2.s| ==> l2.s[i] <= l2.s[j]
 98	        ensures l.capacity == this.capacity + l2.capacity
