102	class OddList extends OddListSpec
103	{
104	    constructor (capacity: nat)
105	        ensures Valid()
106	        ensures |s| == 0
107	        ensures this.capacity == capacity
108	    {
109	        s := [];
110	        this.capacity := capacity;
111	    }
112	
113	    method insert(index: nat, element: Odd)
114	        modifies this
115	        requires 0 <= index <= |s|
116	        requires |s| + 1 <= this.capacity
117	        ensures |s| == |old(s)| + 1
118	        ensures s[index] == element
119	        ensures old(capacity) == capacity
120	        ensures Valid()
121	    {
122	        var tail := s[index..];
123	        s := s[..index] + [element];
124	        s := s + tail;
125	    }
126	
127	    method pushFront(element: Odd)
128	        modifies this
129	        requires |s| + 1 <= this.capacity
130	        ensures |s| == |old(s)| + 1
131	        ensures s[0] == element
132	        ensures old(capacity) == capacity
133	        ensures Valid()
134	    {
135	        insert(0, element);
136	    }
137	
138	    method pushBack(element: Odd)
139	        modifies this
140	        requires |s| + 1 <= this.capacity
141	        ensures |s| == |old(s)| + 1
142	        ensures s[|s| - 1] == element
143	        ensures old(capacity) == capacity
144	        ensures Valid()
145	    {
146	        insert(|s|, element);
147	    }
148	
149	    method remove(element: Odd)
150	        modifies this
151	        requires Valid()
152	        requires |s| > 0
153	        requires element in s
154	        ensures |s| == |old(s)| - 1
155	        ensures old(capacity) == capacity
156	        ensures Valid()
157	    {
158	        for i: int := 0 to |s|
159	            invariant 0 <= i <= |s|
160	            invariant forall k :: 0 <= k < i ==> s[k] != element
161	        {
162	            if s[i] == element
163	            {
164	                s := s[..i] + s[i + 1..];
165	                break;
166	            }
167	        }
168	    }
169	
170	    method removeAtIndex(index: nat)
171	        modifies this
172	        requires Valid()
173	        requires |s| > 0
174	        requires 0 <= index < |s|
175	        ensures |s| == |old(s)| - 1
176	        ensures old(capacity) == capacity
177	        ensures Valid()
178	    {
179	        s := s[..index] + s[index + 1..];
180	    }
181	
182	    method popFront() returns (x: Odd)
183	        modifies this
184	        requires Valid()
185	        requires |s| > 0
186	        ensures old(s)[0] == x
187	        ensures |s| == |old(s)| - 1
188	        ensures old(capacity) == capacity
189	        ensures Valid() 
190	    {
191	        x := s[0];
192	        s := s[1..];
193	    }
194	
195	    method popBack() returns (x: Odd)
196	        modifies this
197	        requires Valid()
198	        requires |s| > 0
199	        ensures old(s)[|old(s)| - 1] == x
200	        ensures |s| == |old(s)| - 1
201	        ensures old(capacity) == capacity
202	        ensures Valid() 
203	    {
204	        x := s[|s| - 1];
205	        s := s[..|s| - 1];
206	    }
207	
208	    method length() returns (n: nat)
209	        ensures n == |s|
210	    {
211	        return |s|;
212	    }
213	
214	    method at(index: nat) returns (x: Odd)
215	    requires 0 <= index < |s|
216	        ensures s[index] == x
217	    {
218	        return s[index];
219	    }
220	
221	    method BinarySearch(element: Odd) returns (index: int)
222	        requires forall i, j :: 0 <= i < j < |s| ==> s[i] <= s[j]
223	        ensures 0 <= index ==> index < |s| && s[index] == element
224	        ensures index == -1 ==> element !in s[..]
225	    {
226	        var left, right := 0, |s|;
227	
228	        while left < right
229	            invariant 0 <= left <= right <= |s|
230	            invariant element !in s[..left] && element !in s[right..]
231	        {
232	            var mid := (left + right) / 2;
233	
234	            if element < s[mid] 
235	            {
236	                right := mid;
237	            } 
238	            else if s[mid] < element 
239	            {
240	                left := mid + 1;
241	            } 
242	            else 
243	            {
244	                return mid;
245	            }
246	        }
247	
248	        return -1;
249	    }
250	
251	    method mergedWith(l2: OddList) returns (l: OddList)
252	        requires Valid()
253	        requires l2.Valid()
254	        requires this.capacity >= 0 
255	        requires l2.capacity >= 0 
256	        requires forall i, j :: 0 <= i < j < |s| ==> s[i] <= s[j]
257	        requires forall i, j :: 0 <= i < j < |l2.s| ==> l2.s[i] <= l2.s[j]
258	        ensures l.capacity == this.capacity + l2.capacity
259	        ensures |l.s| == |s| + |l2.s|
260	    {
261	        l := new OddList(this.capacity + l2.capacity);
262	
263	        var i, j := 0, 0;
264	
265	        while i < |s| || j < |l2.s|
266	            invariant 0 <= i <= |s|
267	            invariant 0 <= j <= |l2.s|
268	            invariant i + j == |l.s|
269	            invariant |l.s| <= l.capacity
270	            invariant l.capacity == this.capacity + l2.capacity
271	            decreases |s| - i, |l2.s| - j
272	        {
273	            if i == |s|
274	            {
275	                if j == |l2.s|
276	                {
277	                    return l;
278	                }
279	                else
280	                {
281	                    l.pushBack(l2.s[j]);
282	                    j := j + 1;
283	                }
284	            }
285	            else
286	            {
287	                if j == |l2.s|
288	                {
289	                    l.pushBack(s[i]);
290	                    i := i + 1;
291	                }
292	                else
293	                {
294	                    if s[i] < l2.s[j]
295	                    {
296	                        l.pushBack(s[i]);
297	                        i := i + 1;
298	                    } 
299	                    else
300	                    {
301	                        l.pushBack(l2.s[j]);
302	                        j := j + 1;
303	                    }
304	                }
305	            }
306	        }
307	
308	        return l;
309	    }
310	}
