312	trait CircularLinkedListSpec<T(==)>
313	{
314	    var l: seq<T>
315	    var capacity: nat 
316	
317	    predicate Valid()
318	        reads this
319	    {
320	        0 <= |l| <= this.capacity
321	    }
322	
323	    method insert(index: int, element: T)
324	    // allows for integer and out-of-bounds index due to circularity
325	    // managed by applying modulus
326	        modifies this
327	        requires |l| + 1 <= this.capacity
328	        ensures |old(l)| == 0 ==> l == [element]
329	        ensures |l| == |old(l)| + 1
330	        ensures |old(l)| > 0 ==> l[index % |old(l)|] == element
331	        ensures old(capacity) == capacity
332	        ensures Valid()
333	
334	    method remove(element: T)
335	        modifies this
336	        requires Valid()
337	        requires |l| > 0
338	        requires element in l
339	        ensures |l| == |old(l)| - 1
340	        ensures old(capacity) == capacity
341	        ensures Valid()
342	
343	    method removeAtIndex(index: int)
344	        modifies this
345	        requires Valid()
346	        requires |l| > 0
347	        ensures |l| == |old(l)| - 1
348	        ensures old(capacity) == capacity
349	        ensures Valid()
350	
351	    method length() returns (n: nat)
352	        ensures n == |l|
353	
354	    method at(index: int) returns (x: T)
355	        requires |l| > 0
356	        ensures l[index % |l|] == x
357	
358	    method nextAfter(index: int) returns (x: T)
359	        requires |l| > 0
360	        ensures |l| == 1 ==> x == l[0]
361	        ensures |l| > 1 && index % |l| == (|l| - 1) ==> x == l[0]
362	        ensures |l| > 1 && 0 <= index && |l| < (|l| - 1) ==> x == l[index % |l| + 1]
363	}
