381	        requires |l| + 1 <= this.capacity
382	        ensures |old(l)| == 0 ==> l == [element]
383	        ensures |l| == |old(l)| + 1
384	        ensures |old(l)| > 0 ==> l[index % |old(l)|] == element
385	        ensures old(capacity) == capacity
386	        ensures Valid()
387	    {
388	        if (|l| == 0)
389	        {
390	            l := [element];
391	        } 
392	        else 
393	        {
394	            var actualIndex := index % |l|;
395	            var tail := l[actualIndex..];
396	            l := l[..actualIndex] + [element];
397	            l := l + tail;
398	        }
399	    }
400	
401	    method remove(element: T)
402	        modifies this
403	        requires Valid()
404	        requires |l| > 0
405	        requires element in l
406	        ensures |l| == |old(l)| - 1
407	        ensures old(capacity) == capacity
408	        ensures Valid()
409	    {
410	        for i: nat := 0 to |l|
411	            invariant 0 <= i <= |l|
412	            invariant forall k :: 0 <= k < i ==> l[k] != element
413	        {
414	            if l[i] == element
415	            {
416	                l := l[..i] + l[i + 1..];
417	                break;
418	            }
419	        }
420	    }
