365	class CircularLinkedList<T(==)> extends CircularLinkedListSpec<T>
366	{
367	    constructor (capacity: nat)
368	        requires capacity >= 0
369	        ensures Valid()
370	        ensures |l| == 0
371	        ensures this.capacity == capacity
372	    {
373	        l := [];
374	        this.capacity := capacity;
375	    }
376	
377	    method insert(index: int, element: T)
378	    // allows for integer and out-of-bounds index due to circularity
379	    // managed by applying modulus
380	        modifies this
381	        requires |l| + 1 <= this.capacity
382	        ensures |old(l)| == 0 ==> l == [element]
383	        ensures |l| == |old(l)| + 1
384	        ensures |old(l)| > 0 ==> l[index % |old(l)|] == element
385	        ensures old(capacity) == capacity
386	        ensures Valid()
387	    {
388	        if (|l| == 0)
389	        {
390	            l := [element];
391	        } 
392	        else 
393	        {
394	            var actualIndex := index % |l|;
395	            var tail := l[actualIndex..];
396	            l := l[..actualIndex] + [element];
397	            l := l + tail;
398	        }
399	    }
400	
401	    method remove(element: T)
402	        modifies this
403	        requires Valid()
404	        requires |l| > 0
405	        requires element in l
406	        ensures |l| == |old(l)| - 1
407	        ensures old(capacity) == capacity
408	        ensures Valid()
409	    {
410	        for i: nat := 0 to |l|
411	            invariant 0 <= i <= |l|
412	            invariant forall k :: 0 <= k < i ==> l[k] != element
413	        {
414	            if l[i] == element
415	            {
416	                l := l[..i] + l[i + 1..];
417	                break;
418	            }
419	        }
420	    }
421	
422	    method removeAtIndex(index: int)
423	        modifies this
424	        requires Valid()
425	        requires |l| > 0
426	        ensures |l| == |old(l)| - 1
427	        ensures old(capacity) == capacity
428	        ensures Valid()
429	    {
430	        var actualIndex := index % |l|;
431	        l := l[..actualIndex] + l[actualIndex + 1..];
432	    }
433	
434	    method length() returns (n: nat)
435	        ensures n == |l|
436	    {
437	        return |l|;
438	    }
439	
440	    method at(index: int) returns (x: T)
441	        requires |l| > 0
442	        ensures l[index % |l|] == x
443	    {
444	        var actualIndex := index % |l|;
445	        return l[actualIndex];
446	    }
447	
448	    method nextAfter(index: int) returns (x: T)
449	        requires |l| > 0
450	        ensures |l| == 1 ==> x == l[0]
451	        ensures |l| > 1 && index % |l| == (|l| - 1) ==> x == l[0]
452	        ensures |l| > 1 && 0 <= index && |l| < (|l| - 1) ==> x == l[index % |l| + 1]
453	    {
454	        if (|l| == 1)
455	        {
456	            x := l[0];
457	        }
458	        else
459	        {
460	            var actualIndex := index % |l|;
461	            if (actualIndex == (|l| - 1))
462	            {
463	                x := l[0];
464	            } else {
465	                x := l[actualIndex + 1];
466	            }
467	        }
468	        
469	        return x;
470	    }
471	
472	    method isIn(element: T) returns (b: bool)
473	        ensures |l| == 0 ==> b == false
474	        ensures |l| > 0 && b == true ==> exists i :: 0 <= i < |l| && l[i] == element
475	        ensures |l| > 0 && b == false ==> !exists i :: 0 <= i < |l| && l[i] == element
476	    {
477	        if (|l| == 0)
478	        {
479	            b := false;
480	        }
481	        else 
482	        {
483	            b := false;
484	            for i: nat := 0 to |l|
485	                invariant 0 <= i <= |l|
486	                invariant forall k :: 0 <= k < i ==> l[k] != element
487	            {
488	                if l[i] == element
489	                {
490	                    b := true;
491	                    break;
492	                }
493	            }
494	        }
495	    }
496	}
